CREATE OR REPLACE PROCEDURE sp(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val real;
    status_text text;
BEGIN
    -- RAM case (strict less-than, priority order)
    IF arg1 < 0 THEN
        result_val := arg1 * -1;
        UPDATE chip_model SET "RAM_MiB" = result_val WHERE "WiFi" = arg2;
    ELSIF arg1 < 10 THEN
        result_val := arg1 + 5;
        DELETE FROM chip_model WHERE "RAM_MiB" = arg1;
    ELSIF arg1 < 20 THEN
        result_val := arg1 * 2;
        UPDATE screen_mode SET "used_kb" = arg3 + result_val WHERE "Pixels" = arg4;
    ELSIF arg1 < 30 THEN
        result_val := arg1 - 8;
        DELETE FROM screen_mode WHERE "used_kb" = arg3;
    ELSE
        result_val := arg1 / 2;
        status_text := 'processed';
    END IF;

    -- Effect 1
    UPDATE phone
    SET "Accreditation_level" = "Accreditation_level" || '_screen_match'
    WHERE "screen_mode" IN (
        SELECT "Graphics_mode"::text FROM screen_mode
        WHERE "Pixels" = arg4 AND "used_kb" = arg3
    );

    -- Effect 2
    UPDATE phone
    SET "Accreditation_type" = "Accreditation_type" || '_wifi_match'
    WHERE "chip_model" IN (
        SELECT "Model_name" FROM chip_model WHERE "WiFi" = arg2
    );

    -- Effect 3
    UPDATE phone
    SET "Hardware_Model_name" = "Hardware_Model_name" || '_ram_wifi_match'
    WHERE "chip_model" IN (
        SELECT "Model_name" FROM chip_model
        WHERE "RAM_MiB" = arg1 AND "WiFi" = arg2
    );

    -- Effect 4
    UPDATE phone
    SET "Accreditation_type" = "Accreditation_type" || '_dual_match'
    WHERE "chip_model" IN (
        SELECT "Model_name" FROM chip_model WHERE "WiFi" = arg2
    )
    AND "screen_mode" IN (
        SELECT "Graphics_mode"::text FROM screen_mode WHERE "Pixels" = arg4
    );

    -- Effect 5
    UPDATE chip_model
    SET "WiFi" = arg2 || status_text
    WHERE "RAM_MiB" = arg1;

    -- Effect 6
    result_val := result_val + 3;

    -- Effect 7
    UPDATE screen_mode
    SET "Pixels" = arg4 || '_updated'
    WHERE "used_kb" = arg3;

    -- Effect 8
    DELETE FROM chip_model WHERE "RAM_MiB" > result_val;

    -- Effect 9
    status_text := 'pending';

    -- Effect 10
    UPDATE screen_mode
    SET "used_kb" = arg3 + 12
    WHERE "Pixels" = arg4;

    -- Effect 11
    UPDATE chip_model
    SET "RAM_MiB" = result_val
    WHERE "WiFi" = arg2;

    -- Effect 12
    result_val := result_val - 7;

    -- Effect 13
    DELETE FROM screen_mode WHERE "Pixels" = arg4 || '_old';

    -- Effect 14
    UPDATE chip_model
    SET "WiFi" = arg2 || '_final'
    WHERE "RAM_MiB" = arg1;

    -- Effect 15
    status_text := 'completed';

    -- Effect 16
    UPDATE screen_mode
    SET "used_kb" = arg3 * 3
    WHERE "Pixels" = arg4;

    -- Effect 17
    DELETE FROM chip_model WHERE "WiFi" = arg2 || status_text;
END;
$$;

